Are the two triangles congruent?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (A) at (0,0);
\coordinate (B) at (1.8,0);
\coordinate (C) at (0,1.2);
\coordinate (D) at (3.0,0);
\coordinate (E) at (5.7,0);
\coordinate (F) at (3.0,1.8);
\draw (A) -- (B) node[midway, below] {$6\text{ cm}$};
\draw (B) -- (C);
\draw (C) -- (A) node[midway, left] {$4\text{ cm}$};
\draw (D) -- (E) node[midway, below] {$9\text{ cm}$};
\draw (E) -- (F);
\draw (F) -- (D) node[midway, left] {$6\text{ cm}$};
\coordinate (ra1) at ($(A)!0.25cm!(B)$);
\coordinate (ra2) at ($(A)!0.25cm!(C)$);
\draw (ra1) -- ($(ra1)+(ra2)-(A)$) -- (ra2);
\coordinate (rd1) at ($(D)!0.25cm!(E)$);
\coordinate (rd2) at ($(D)!0.25cm!(F)$);
\draw (rd1) -- ($(rd1)+(rd2)-(D)$) -- (rd2);
\end{tikzpicture}
[/tikz]

Name the single transformation that moves quadrilateral $ABCD$ onto quadrilateral $EFGH$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,0);
\coordinate (B) at (2.0,0.2);
\coordinate (C) at (2.4,1.4);
\coordinate (D) at (0.4,1.2);
\coordinate (E) at (3.3,0.5);
\coordinate (F) at (5.3,0.7);
\coordinate (G) at (5.7,1.9);
\coordinate (H) at (3.7,1.7);
\draw (A) -- (B) -- (C) -- (D) -- cycle;
\draw (E) -- (F) -- (G) -- (H) -- cycle;
\node[below left] at (A) {$A$};
\node[below right] at (B) {$B$};
\node[above right] at (C) {$C$};
\node[above left] at (D) {$D$};
\node[below left] at (E) {$E$};
\node[below right] at (F) {$F$};
\node[above right] at (G) {$G$};
\node[above left] at (H) {$H$};
\end{tikzpicture}
[/tikz]

$\triangle ABC$ has been moved onto $\triangle DEF$ by a single transformation. Which transformation was used?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,0);
\coordinate (B) at (2.4,0);
\coordinate (C) at (2.0,1.3);
\coordinate (D) at (4.2,2.6);
\coordinate (E) at (4.2,0.2);
\coordinate (F) at (5.5,0.6);
\draw (A) -- (B) -- (C) -- cycle;
\draw (D) -- (E) -- (F) -- cycle;
\node[below left] at (A) {$A$};
\node[below right] at (B) {$B$};
\node[above] at (C) {$C$};
\node[above] at (D) {$D$};
\node[below left] at (E) {$E$};
\node[below right] at (F) {$F$};
\end{tikzpicture}
[/tikz]

The triangles are congruent. Use the matching marks to name the vertex in $\triangle RST$ that corresponds to vertex $K$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{decorations.markings}
\tikzset{
  tickmark/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}},
  tickmark2/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-2pt,-4pt) -- (-2pt,4pt);
                               \draw[black] (2pt,-4pt) -- (2pt,4pt);}}}},
  tickmark3/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-3pt,-4pt) -- (-3pt,4pt);
                               \draw[black] (0pt,-4pt) -- (0pt,4pt);
                               \draw[black] (3pt,-4pt) -- (3pt,4pt);}}}},
}
\coordinate (J) at (0,0.2);
\coordinate (K) at (1.9,1.6);
\coordinate (L) at (2.5,0);
\coordinate (R) at (6.4,1.5);
\coordinate (S) at (4.5,0.1);
\coordinate (T) at (3.9,1.7);
\draw[tickmark] (J) -- (K);
\draw[tickmark2] (K) -- (L);
\draw[tickmark3] (J) -- (L);
\draw[tickmark] (R) -- (S);
\draw[tickmark2] (S) -- (T);
\draw[tickmark3] (R) -- (T);
\node[below left] at (J) {$J$};
\node[above] at (K) {$K$};
\node[below right] at (L) {$L$};
\node[above right] at (R) {$R$};
\node[below] at (S) {$S$};
\node[above left] at (T) {$T$};
\end{tikzpicture}
[/tikz]

The quadrilaterals are congruent. $PQRS$ has been reflected to give $WXYZ$. Name the side in $WXYZ$ that corresponds to side $QR$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (P) at (0,1.5);
\coordinate (Q) at (1.2,1.5);
\coordinate (R) at (2.0,0);
\coordinate (S) at (0,0);
\coordinate (W) at (5.6,1.5);
\coordinate (X) at (4.4,1.5);
\coordinate (Y) at (3.6,0);
\coordinate (Z) at (5.6,0);
\draw (P) -- (Q) -- (R) -- (S) -- cycle;
\draw (W) -- (X) -- (Y) -- (Z) -- cycle;
\node[above] at (P) {$P$};
\node[above] at (Q) {$Q$};
\node[below] at (R) {$R$};
\node[below] at (S) {$S$};
\node[above] at (W) {$W$};
\node[above] at (X) {$X$};
\node[below] at (Y) {$Y$};
\node[below] at (Z) {$Z$};
\end{tikzpicture}
[/tikz]

The triangles are congruent. Use the angle marks to name the angle in $\triangle UVW$ that corresponds to $\angle E$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{angles}
\coordinate (D) at (0,0);
\coordinate (E) at (2.6,0.4);
\coordinate (F) at (1.0,1.8);
\coordinate (U) at (6.3,2.0);
\coordinate (V) at (3.7,1.6);
\coordinate (W) at (5.3,0.2);
\draw (D) -- (E) -- (F) -- cycle;
\draw (U) -- (V) -- (W) -- cycle;
\pic[draw, angle radius=0.45cm] {angle = E--D--F};
\pic[draw, angle radius=0.38cm] {angle = F--E--D};
\pic[draw, angle radius=0.52cm] {angle = F--E--D};
\pic[draw, angle radius=0.45cm] {angle = V--U--W};
\pic[draw, angle radius=0.38cm] {angle = W--V--U};
\pic[draw, angle radius=0.52cm] {angle = W--V--U};
\node[below left] at (D) {$D$};
\node[below right] at (E) {$E$};
\node[above] at (F) {$F$};
\node[above right] at (U) {$U$};
\node[above left] at (V) {$V$};
\node[below] at (W) {$W$};
\end{tikzpicture}
[/tikz]

The rectangle and the parallelogram both have sides of $7$ m and $4$ m. Are the two shapes congruent?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw (0,0) rectangle (2.1,1.2);
\node[below] at (1.05,0) {$7\text{ m}$};
\node[right] at (2.1,0.6) {$4\text{ m}$};
\draw (3.3,0) -- (5.4,0) -- (6.0,1.04) -- (3.9,1.04) -- cycle;
\node[below] at (4.35,0) {$7\text{ m}$};
\draw (5.4,0) -- (6.0,1.04) node[midway, below right] {$4\text{ m}$};
\end{tikzpicture}
[/tikz]

Name the single transformation that moves figure $A$ onto figure $B$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw (0,0) -- (1.8,0) -- (1.8,0.9) -- (0.5,1.7) -- (0,0.9) -- cycle;
\draw (5.6,0) -- (3.8,0) -- (3.8,0.9) -- (5.1,1.7) -- (5.6,0.9) -- cycle;
\node[below] at (0.9,-0.15) {$A$};
\node[below] at (4.7,-0.15) {$B$};
\end{tikzpicture}
[/tikz]
